function validate(input) {
  const [{ products = [], sales = [] }] = input;
  const known = new Set(), spelling = new Map(), ids = new Set();
  for (const [id, name, category] of products) {
    if ([id, name, category].includes(null)) return 'No value in products may be null.';
    if (known.has(id)) return `product_id ${id} appears twice in products.`;
    known.add(id);
    const folded = String(category).toLowerCase();
    if (spelling.has(folded) && spelling.get(folded) !== category) return `Categories ${spelling.get(folded)} and ${category} differ only in letter case.`;
    spelling.set(folded, category);
  }
  for (const [id, product, day, quantity, price] of sales) {
    if ([id, product, day, quantity, price].includes(null)) return 'No value in sales may be null.';
    if (ids.has(id)) return `sale_id ${id} appears twice in sales.`;
    ids.add(id);
    if (!known.has(product)) return `product_id ${product} is not in products.`;
    if (!/^\d{4}-(0[1-9]|1[0-2])-\d{2}$/.test(day)) return `sale_date ${day} must look like 2023-01-31.`;
    if (!(quantity > 0) || !(price > 0)) return 'quantity and price must be positive.';
  }
  return null;
}

