function generate(rand, size) {
  const small = size === 'small';
  const pick = list => list[Math.floor(rand() * list.length)];
  const pad = n => String(n).padStart(2, '0');
  const categories = small ? ['Apparel', 'Kitchen', 'Tech', 'Fitness'] : ['Apparel', 'Kitchen', 'Tech', 'Fitness', 'Garden', 'Toys', 'Books', 'Home Audio'];
  const words = ['Warm', 'Smart', 'Yoga', 'Designer', 'Cutting', 'Mini', 'Classic'];
  const productCount = small ? 1 + Math.floor(rand() * 5) : 50;
  const products = [];
  for (let i = 0; i < productCount; i++) products.push([i + 1, `${pick(words)} Item ${i + 1}`, pick(categories)]);
  // Prices are whole or quarter amounts, so sums stay exact and revenue ties are real ties.
  const prices = small ? [10, 15, 20, 12.5] : [5, 7.25, 10, 12.5, 15, 18, 20, 24.75, 30, 49.5];
  const count = small ? Math.floor(rand() * 9) : 2000;
  const sales = [];
  for (let i = 0; i < count; i++) {
    const year = 2022 + Math.floor(rand() * 3), month = 1 + Math.floor(rand() * 12), day = 1 + Math.floor(rand() * 28);
    sales.push([small ? i + 1 : 1000 + i, pick(products)[0], `${year}-${pad(month)}-${pad(day)}`, 1 + Math.floor(rand() * (small ? 3 : 10)), pick(prices)]);
  }
  return [{ products, sales }];
}
